import { bench, group, run } from 'mitata';
import { clsx } from '../src/index.js';
import { clsx as lite } from '../src/lite.js';

// Strings
group('Strings', () => {
	bench('clsx', () => clsx('foo', '', 'bar', 'baz', 'bax', 'bux'));
	bench('clsx/lite', () => lite('foo', '', 'bar', 'baz', 'bax', 'bux'));
});

// Objects
group('Objects', () => {
	bench('clsx', () => clsx({ foo: true, bar: true, bax: true, bux: false }, { baz: true, bax: false, bux: true }));
	bench('clsx/lite', () => lite({ foo: true, bar: true, bax: true, bux: false }, { baz: true, bax: false, bux: true }));
});

// Arrays
group('Arrays', () => {
	bench('clsx', () => clsx(['foo', 'bar'], ['baz', 'bax', 'bux']));
	bench('clsx/lite', () => lite(['foo', 'bar'], ['baz', 'bax', 'bux']));
});

// Mixed
group('Mixed', () => {
	bench('clsx', () => clsx('foo', 'bar', { bax: true, bux: false }, ['baz', { bax: false, bux: true }]));
	bench('clsx/lite', () => lite('foo', 'bar', { bax: true, bux: false }, ['baz', { bax: false, bux: true }]));
});

await run();

